    wire logic signed [4:0] r1_6 = 5'(l1n6_w31) >>> 0;
    wire logic [0:0] n1_6 = r1_6[4] ? 1'd0 : ((r1_6 > 5'sd1) ? {1{1'b1}} : r1_6[0:0]);
    wire logic signed [1:0] l1n7_w1 = 2'($signed({1'b0, qn0_0}));
    wire logic signed [1:0] l1n7_w2 = 2'($signed({1'b0, qn0_1}));
    wire logic signed [1:0] l1n7_w3 = 2'($signed({1'b0, qn0_2}));
    wire logic signed [1:0] l1n7_w4 = 2'($signed({1'b0, qn0_3}));
    wire logic signed [1:0] l1n7_w5 = 2'($signed({1'b0, qn0_4}));
    wire logic signed [1:0] l1n7_w6 = 2'($signed({1'b0, qn0_5}));
    wire logic signed [1:0] l1n7_w7 = 2'($signed({1'b0, qn0_6}));
    wire logic signed [1:0] l1n7_w8 = 2'($signed({1'b0, qn0_7}));
    wire logic signed [1:0] l1n7_w9 = 2'($signed({1'b0, qn0_8}));
    wire logic signed [1:0] l1n7_w10 = 2'($signed({1'b0, qn0_9}));
    wire logic signed [1:0] l1n7_w11 = 2'($signed({1'b0, qn0_10}));
    wire logic signed [1:0] l1n7_w12 = 2'($signed({1'b0, qn0_11}));
    wire logic signed [1:0] l1n7_w13 = 2'($signed({1'b0, qn0_12}));
    wire logic signed [1:0] l1n7_w14 = 2'($signed({1'b0, qn0_13}));
    wire logic signed [1:0] l1n7_w15 = 2'($signed({1'b0, qn0_14}));
    wire logic signed [1:0] l1n7_w16 = 2'($signed({1'b0, qn0_15}));
    wire logic signed [1:0] l1n7_w17 = 2'sd1;
    wire logic signed [1:0] l1n7_w18 = 2'(l1n7_w1) - 2'(l1n7_w2);
    wire logic signed [1:0] l1n7_w19 = 2'(l1n7_w3) - 2'(l1n7_w4);
    wire logic signed [2:0] l1n7_w20 = 3'(l1n7_w5) + 3'(l1n7_w6);
    wire logic signed [2:0] l1n7_w21 = 3'(l1n7_w7) + 3'(l1n7_w8);
    wire logic signed [2:0] l1n7_w22 = 3'(l1n7_w9) + 3'(l1n7_w10);
    wire logic signed [1:0] l1n7_w23 = 2'(l1n7_w12) - 2'(l1n7_w11);
    wire logic signed [1:0] l1n7_w24 = 2'(l1n7_w14) - 2'(l1n7_w13);
    wire logic signed [1:0] l1n7_w25 = 2'(l1n7_w16) - 2'(l1n7_w15);
    wire logic signed [2:0] l1n7_w26 = 3'(l1n7_w18) + 3'(l1n7_w19);
    wire logic signed [2:0] l1n7_w27 = 3'(l1n7_w21) - 3'(l1n7_w20);
    wire logic signed [2:0] l1n7_w28 = 3'(l1n7_w22) + 3'(l1n7_w23);
    wire logic signed [2:0] l1n7_w29 = 3'(l1n7_w24) + 3'(l1n7_w25);
    wire logic signed [3:0] l1n7_w30 = 4'(l1n7_w26) + 4'(l1n7_w27);
    wire logic signed [3:0] l1n7_w31 = 4'(l1n7_w28) + 4'(l1n7_w29);
    wire logic signed [4:0] l1n7_w32 = 5'(l1n7_w30) + 5'(l1n7_w31);
    wire logic signed [4:0] l1n7_w33 = 5'(l1n7_w32) - 5'(l1n7_w17);
    wire logic signed [4:0] r1_7 = 5'(l1n7_w33) >>> 0;
    wire logic [0:0] n1_7 = r1_7[4] ? 1'd0 : ((r1_7 > 5'sd1) ? {1{1'b1}} : r1_7[0:0]);
    logic [0:0] qn1_0;
    logic [0:0] qn1_1;
    logic [0:0] qn1_2;
    logic [0:0] qn1_3;
    logic [0:0] qn1_4;
    logic [0:0] qn1_5;
    logic [0:0] qn1_6;
    logic [0:0] qn1_7;
    always_ff @(posedge clk) begin
        qn1_0 <= n1_0;
        qn1_1 <= n1_1;
        qn1_2 <= n1_2;
        qn1_3 <= n1_3;
        qn1_4 <= n1_4;
        qn1_5 <= n1_5;
        qn1_6 <= n1_6;
        qn1_7 <= n1_7;
    end
    // layer 3: 3 neurons x 8 inputs, class scores (signed)
    wire logic signed [1:0] l2n0_w1 = 2'($signed({1'b0, qn1_0}));
    wire logic signed [1:0] l2n0_w2 = 2'($signed({1'b0, qn1_1}));
    wire logic signed [1:0] l2n0_w3 = 2'($signed({1'b0, qn1_2}));
    wire logic signed [1:0] l2n0_w4 = 2'($signed({1'b0, qn1_3}));
    wire logic signed [1:0] l2n0_w5 = 2'($signed({1'b0, qn1_4}));
    wire logic signed [1:0] l2n0_w6 = 2'($signed({1'b0, qn1_5}));
    wire logic signed [1:0] l2n0_w7 = 2'($signed({1'b0, qn1_6}));
    wire logic signed [1:0] l2n0_w8 = 2'($signed({1'b0, qn1_7}));
    wire logic signed [1:0] l2n0_w9 = 2'sd1;
    wire logic signed [1:0] l2n0_w10 = 2'(l2n0_w1) - 2'(l2n0_w2);
    wire logic signed [1:0] l2n0_w11 = 2'(l2n0_w4) - 2'(l2n0_w3);
    wire logic signed [2:0] l2n0_w12 = 3'(l2n0_w5) + 3'(l2n0_w6);
    wire logic signed [2:0] l2n0_w13 = 3'(l2n0_w7) + 3'(l2n0_w8);
    wire logic signed [2:0] l2n0_w14 = 3'(l2n0_w10) + 3'(l2n0_w11);
    wire logic signed [2:0] l2n0_w15 = 3'(l2n0_w13) - 3'(l2n0_w12);
    wire logic signed [3:0] l2n0_w16 = 4'(l2n0_w14) + 4'(l2n0_w15);
    wire logic signed [3:0] l2n0_w17 = 4'(l2n0_w16) - 4'(l2n0_w9);
    wire logic signed [3:0] n2_0 = l2n0_w17;
    wire logic signed [1:0] l2n1_w1 = 2'($signed({1'b0, qn1_0}));
    wire logic signed [1:0] l2n1_w2 = 2'($signed({1'b0, qn1_1}));
    wire logic signed [1:0] l2n1_w3 = 2'($signed({1'b0, qn1_2}));
    wire logic signed [1:0] l2n1_w4 = 2'($signed({1'b0, qn1_3}));
    wire logic signed [1:0] l2n1_w5 = 2'($signed({1'b0, qn1_4}));
    wire logic signed [1:0] l2n1_w6 = 2'($signed({1'b0, qn1_5}));
    wire logic signed [1:0] l2n1_w7 = 2'($signed({1'b0, qn1_6}));
    wire logic signed [1:0] l2n1_w8 = 2'($signed({1'b0, qn1_7}));
    wire logic signed [1:0] l2n1_w9 = 2'sd1;
    wire logic signed [2:0] l2n1_w10 = 3'(l2n1_w1) + 3'(l2n1_w2);
    wire logic signed [2:0] l2n1_w11 = 3'(l2n1_w3) + 3'(l2n1_w4);
    wire logic signed [1:0] l2n1_w12 = 2'(l2n1_w6) - 2'(l2n1_w5);
    wire logic signed [1:0] l2n1_w13 = 2'(l2n1_w8) - 2'(l2n1_w7);
    wire logic signed [2:0] l2n1_w14 = 3'(l2n1_w10) - 3'(l2n1_w11);
    wire logic signed [2:0] l2n1_w15 = 3'(l2n1_w12) + 3'(l2n1_w13);
    wire logic signed [3:0] l2n1_w16 = 4'(l2n1_w14) + 4'(l2n1_w15);
    wire logic signed [3:0] l2n1_w17 = 4'(l2n1_w16) + 4'(l2n1_w9);
    wire logic signed [3:0] n2_1 = l2n1_w17;
    wire logic signed [1:0] l2n2_w1 = 2'($signed({1'b0, qn1_0}));
    wire logic signed [1:0] l2n2_w2 = 2'($signed({1'b0, qn1_1}));
    wire logic signed [1:0] l2n2_w3 = 2'($signed({1'b0, qn1_2}));
    wire logic signed [1:0] l2n2_w4 = 2'($signed({1'b0, qn1_3}));
    wire logic signed [1:0] l2n2_w5 = 2'($signed({1'b0, qn1_4}));
    wire logic signed [1:0] l2n2_w6 = 2'($signed({1'b0, qn1_5}));
    wire logic signed [1:0] l2n2_w7 = 2'($signed({1'b0, qn1_6}));
    wire logic signed [1:0] l2n2_w8 = 2'($signed({1'b0, qn1_7}));
    wire logic signed [1:0] l2n2_w9 = 2'(l2n2_w2) - 2'(l2n2_w1);
    wire logic signed [2:0] l2n2_w10 = 3'(l2n2_w3) + 3'(l2n2_w4);
    wire logic signed [2:0] l2n2_w11 = 3'(l2n2_w5) + 3'(l2n2_w6);
    wire logic signed [1:0] l2n2_w12 = 2'(l2n2_w7) - 2'(l2n2_w8);
    wire logic signed [2:0] l2n2_w13 = 3'(l2n2_w9) - 3'(l2n2_w10);
    wire logic signed [2:0] l2n2_w14 = 3'(l2n2_w11) + 3'(l2n2_w12);
    wire logic signed [3:0] l2n2_w15 = 4'(l2n2_w13) + 4'(l2n2_w14);
    wire logic signed [3:0] n2_2 = l2n2_w15;
    logic signed [3:0] qn2_0;
    logic signed [3:0] qn2_1;
    logic signed [3:0] qn2_2;
    always_ff @(posedge clk) begin
        qn2_0 <= n2_0;
        qn2_1 <= n2_1;
        qn2_2 <= n2_2;
    end
    // class scores and argmax, ties to the lowest class index
    wire logic signed [3:0] s0 = 4'(qn2_0);
    wire logic signed [3:0] s1 = 4'(qn2_1);
    wire logic signed [3:0] s2 = 4'(qn2_2);
    wire logic       ge10 = s1 > s0;
    wire logic signed [3:0] m01 = ge10 ? s1 : s0;
    wire logic [1:0] c01 = ge10 ? 2'd1 : 2'd0;
    wire logic [1:0] cls = (s2 > m01) ? 2'd2 : c01;
    logic [LATENCY-1:0] vpipe;
    always_ff @(posedge clk) begin
        out_cls <= cls;
        if (rst) vpipe <= '0; else vpipe <= {vpipe[LATENCY-2:0], in_v};
    end
    assign out_v = vpipe[LATENCY-1];
endmodule
`default_nettype wire
/* verilator lint_on UNUSEDSIGNAL */
